<?php
declare(strict_types=1);
use WebSitePlus\Auth\TokenService;
use WebSitePlus\Core\Config;
// Uses only the random schemas created by integration.php, never original worker data.
if(!isset($db,$source,$activeAccessId,$devicePrivateKey) || !preg_match('/^audit[a-f0-9]{6}_asistencia_test$/D',$source))throw new RuntimeException('Isolated harness required');
$db->exec('UPDATE wp_intentos_login SET creado_en=DATE_SUB(NOW(),INTERVAL 1 DAY)');
$enrollToken=TokenService::createSession(1,null,'PASSWORD','127.0.0.1',$fixtureUser['password'])['access_token'];
$secondOwnEnrollToken=TokenService::createSession(1,null,'PASSWORD','127.0.0.1',$fixtureUser['password'])['access_token'];
$otherEnrollToken=TokenService::createSession(2,null,'PASSWORD','127.0.0.1',$adminUser['password'])['access_token'];
$biometricEnrollToken=TokenService::createSession(1,null,'BIOMETRIA','127.0.0.1',$fixtureUser['password'],'ANDROID',$activeAccessId)['access_token'];
$oldEnrollToken=TokenService::createSession(1,null,'PASSWORD','127.0.0.1',$fixtureUser['password'])['access_token'];
$db->prepare('UPDATE wp_sesiones SET creada_en=DATE_SUB(NOW(),INTERVAL 10 MINUTE) WHERE access_hash=?')->execute([hash('sha256',$oldEnrollToken)]);
$sourceFaceBefore=$admin->query("SELECT rostro_descriptor FROM `$source`.trabajadores WHERE id_trabajador=1")->fetchColumn();
check(api('/auth/face/enrollment/status',['id_acceso'=>$activeAccessId,'device_uid'=>$activeDeviceUid],$enrollToken)['data']['reference_source']==='ASISTENCIA','Hybrid face uses existing attendance reference without enrollment');
check(api('/auth/face/enrollment/challenge',['id_acceso'=>$activeAccessId,'device_uid'=>$activeDeviceUid,'perfil_sha256'=>str_repeat('a',64)],$enrollToken)['error_code']==='FACE_ALREADY_IN_ATTENDANCE','Hybrid face prevents unnecessary duplicate registration');
$admin->exec("UPDATE `$source`.trabajadores SET rostro_descriptor=NULL WHERE id_trabajador=1");
$sourceFaceBefore=null;
$androidRowsBefore=$db->query('SELECT * FROM wp_accesos_android ORDER BY id_acceso')->fetchAll();
$faceSessionsBefore=(int)$db->query('SELECT COUNT(*) FROM wp_sesiones')->fetchColumn();
$samples=array_fill(0,3,array_fill(0,128,.05));$samples[1][0]=.06;$samples[2][0]=.07;
$payload=json_encode($samples,JSON_THROW_ON_ERROR);
$enrollIdentity=['id_acceso'=>$activeAccessId,'device_uid'=>$activeDeviceUid];
$digestBody=$enrollIdentity+['perfil_sha256'=>hash('sha256',$payload),'id_usuario'=>2];
check(api('/auth/face/enrollment/status',$enrollIdentity)['code']===401,'Face enrollment requires an authenticated session');
check(api('/auth/face/enrollment/status',$enrollIdentity,$otherEnrollToken)['code']===403,'Face enrollment isolates account from device owner');
check(api('/auth/face/enrollment/status',array_replace($enrollIdentity,['device_uid'=>$unknownDeviceUid]),$enrollToken)['code']===403,'Face enrollment rejects another phone');
check(api('/auth/face/enrollment/status',$enrollIdentity,$enrollToken)['data']['registered']===false,'Face enrollment starts without a stored profile');
check(api('/auth/face/enrollment/challenge',$digestBody,$biometricEnrollToken)['error_code']==='FRESH_PASSWORD_REQUIRED','Face enrollment requires recent password, not biometric session alone');
check(api('/auth/face/enrollment/challenge',$digestBody,$oldEnrollToken)['error_code']==='FRESH_PASSWORD_REQUIRED','Face enrollment rejects stale password session');
check(api('/auth/face/enrollment/status',$enrollIdentity,$oldEnrollToken)['data']['recent_password']===false,'Face enrollment reports password renewal before opening camera');
$makeEnrollmentChallenge=fn()=>api('/auth/face/enrollment/challenge',$digestBody,$enrollToken)['data'];
$enrollmentProof=function(array $challenge,mixed $key)use($enrollIdentity,$payload,$signMessage){return $enrollIdentity+['challenge_id'=>$challenge['challenge_id'],'firma_base64'=>$signMessage($challenge['message'],$key),'perfil_json'=>$payload];};
$enrollmentChallenge=$makeEnrollmentChallenge();
check(api('/auth/face/enrollment/confirm',$enrollmentProof($enrollmentChallenge,$foreignPrivateKey),$enrollToken)['code']===401,'Face enrollment rejects foreign signing key');
check(api('/auth/face/enrollment/confirm',$enrollmentProof($enrollmentChallenge,$devicePrivateKey),$enrollToken)['code']===401,'Face enrollment invalid signature consumes challenge');
$enrollmentChallenge=$makeEnrollmentChallenge();$proof=$enrollmentProof($enrollmentChallenge,$devicePrivateKey);
$altered=$samples;$altered[1][0]=.08;
check(api('/auth/face/enrollment/confirm',array_replace($proof,['perfil_json'=>json_encode($altered)]),$enrollToken)['code']===401,'Face enrollment binds exact profile bytes to signature');
check(api('/auth/face/enrollment/confirm',$proof,$secondOwnEnrollToken)['code']===401,'Face enrollment signature cannot move to another session of same account');
check(api('/auth/face/enrollment/confirm',array_replace($proof,['perfil_json'=>json_encode((object)$samples)]),$enrollToken)['code']===422,'Face enrollment rejects JSON objects disguised as arrays');
check(api('/auth/face/enrollment/confirm',array_replace($proof,['perfil_json'=>'[]']),$enrollToken)['code']===422,'Face enrollment rejects missing samples');
$bad=$samples;$bad[0][0]='0.05';
check(api('/auth/face/enrollment/confirm',array_replace($proof,['perfil_json'=>json_encode($bad)]),$enrollToken)['code']===422,'Face enrollment rejects numeric strings');
$bad=$samples;$bad[0]=array_fill(0,128,0);
check(api('/auth/face/enrollment/confirm',array_replace($proof,['perfil_json'=>json_encode($bad)]),$enrollToken)['code']===422,'Face enrollment rejects blank embeddings');
$bad=$samples;$bad[0][0]=2;
check(api('/auth/face/enrollment/confirm',array_replace($proof,['perfil_json'=>json_encode($bad)]),$enrollToken)['code']===422,'Face enrollment rejects inconsistent samples');
$loginChallenge=WebSitePlus\Auth\AndroidAccessService::challenge($activeAccessId,$activeDeviceUid,'127.0.0.1');
check(api('/auth/face/enrollment/confirm',$enrollmentProof($loginChallenge,$devicePrivateKey),$enrollToken)['code']===401,'Face enrollment cannot consume fingerprint login challenge');
$db->exec('UPDATE wp_intentos_login SET creado_en=DATE_SUB(NOW(),INTERVAL 1 DAY)');
$enrollmentChallenge=$makeEnrollmentChallenge();$proof=$enrollmentProof($enrollmentChallenge,$devicePrivateKey);
$saved=api('/auth/face/enrollment/confirm',$proof,$enrollToken);
check($saved['code']===200 && $saved['data']['registered']===true && $saved['data']['estado']==='PENDIENTE_VALIDACION' && $saved['data']['facial_login_enabled']===false,'Face enrollment persists profile without enabling facial login');
$stored=$db->query('SELECT * FROM wp_rostros_cuenta WHERE id_usuario=1')->fetch();
check($stored!==false && $stored['id_usuario']==1 && $stored['id_acceso_android']==$activeAccessId,'Face enrollment ignores injected account id and binds authorized device');
$encryptionKey=hash_hkdf('sha256',(string)Config::get('security.jwt_secret'),32,'websiteplus.face.enrollment.v1');
$plain=openssl_decrypt(base64_decode($stored['perfil_cifrado']),'aes-256-gcm',$encryptionKey,OPENSSL_RAW_DATA,base64_decode($stored['iv_base64']),base64_decode($stored['tag_base64']),'WSP_FACE_V1:1:'.$activeAccessId);
check($plain===$payload && !str_contains($stored['perfil_cifrado'],$payload),'Face enrollment stores authenticated ciphertext and preserves actual samples');
check(@openssl_decrypt(base64_decode($stored['perfil_cifrado']),'aes-256-gcm',$encryptionKey,OPENSSL_RAW_DATA,base64_decode($stored['iv_base64']),base64_decode($stored['tag_base64']),'WSP_FACE_V1:2:'.$activeAccessId)===false,'Face enrollment ciphertext is bound to account and device');
check(api('/auth/face/enrollment/confirm',$proof,$enrollToken)['code']===409,'Face enrollment cannot overwrite existing profile or replay registration');
check(api('/auth/face/enrollment/challenge',$digestBody,$enrollToken)['code']===409,'Face enrollment duplicate registration rejected');
check(api('/auth/face/enrollment/status',$enrollIdentity,$enrollToken)['data']['registered']===true,'Face enrollment status reloads saved profile from database');
check(!str_contains(json_encode($saved),$payload) && !str_contains(json_encode(api('/auth/face/enrollment/status',$enrollIdentity,$enrollToken)),'perfil_cifrado'),'Face enrollment API never returns biometric samples or ciphertext');
check((int)$db->query('SELECT COUNT(*) FROM wp_sesiones')->fetchColumn()===$faceSessionsBefore,'Face enrollment issues zero sessions');
check($admin->query("SELECT rostro_descriptor FROM `$source`.trabajadores WHERE id_trabajador=1")->fetchColumn()===$sourceFaceBefore,'Face enrollment leaves attendance descriptors unchanged');
check($db->query('SELECT * FROM wp_accesos_android ORDER BY id_acceso')->fetchAll()===$androidRowsBefore,'Face enrollment leaves V011 keys and bindings unchanged');
check(api('/auth/logout',[],$enrollToken)['code']===200,'Face enrollment owner can log out normally');
$newEnrollmentToken=TokenService::createSession(1,null,'PASSWORD','127.0.0.1',$fixtureUser['password'])['access_token'];
check(api('/auth/face/enrollment/status',$enrollIdentity,$newEnrollmentToken)['data']['registered']===true,'Face enrollment persists across logout and new password session');
